'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,permissions:[],boot:null,page:'overview',dataset:'all',q:'',pageNo:1,list:null,core:null,sequence:0,initialPassword:'',resetToken:new URLSearchParams(location.search).get('token')||''};
const nav=[['PROGRAMME',[['overview','Overview','◈'],['plans','IT Control Plan','▦'],['risks','Risk Register','◇'],['library','Control Library','▤'],['reviews','Audit & Reviews','☷'],['tests','Control Testing','✓']]],['ASSURANCE',[['evidence','Evidence Management','▣'],['findings','Findings Management','!'],['actions','Remediation Actions','↗'],['changes','Change Management','⇄']]],['TECHNOLOGY & SUPPLIERS',[['slas','SLA Management','◷'],['assets','Asset Register','▧'],['licences','Licence Management','↻'],['integrations','Integrations','⌁']]],['MANAGEMENT',[['reports','Reporting','▥'],['notifications','Notifications','✉'],['users','Users & Access','♙'],['audit','Audit Trail','≡'],['organizations','Customer Organisations','◎'],['settings','Settings','⚙']]]];
const labels=Object.fromEntries(nav.flatMap(g=>g[1]).map(x=>[x[0],x[1]]));
const has=p=>state.permissions.includes(p),today=()=>new Date().toISOString().slice(0,10);
const fmt=v=>v?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v)):'—';
const badge=v=>'<span class="badge '+esc(String(v||'').toLowerCase().replace(/[^a-z]+/g,'-'))+'">'+esc(v||'—')+'</span>';
const sample=r=>r.is_sample?'<span class="badge sample">Sample</span>':'';
const button=(label,action,id='',kind='secondary')=>'<button class="button '+kind+'" data-action="'+action+'" data-id="'+esc(id)+'">'+label+'</button>';
const input=(name,value='',type='text',required=false,extra='')=>'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(required?'required ':'')+extra+'>';
const field=(label,body,wide=false,hint='')=>'<label class="field '+(wide?'wide':'')+'"><span>'+label+'</span>'+body+(hint?'<small>'+hint+'</small>':'')+'</label>';
const options=(items,value,empty='Select…')=>'<option value="">'+empty+'</option>'+items.map(x=>'<option value="'+esc(x.value??x.id)+'" '+(String(x.value??x.id)===String(value)?'selected':'')+'>'+esc(x.label??x.name??x.title??x.reference)+'</option>').join('');
function notify(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast visible'+(error?' error':'');setTimeout(()=>el.className='toast',6500)}
async function api(url,init={}){const headers={...(init.headers||{})};if(init.body&&!(init.body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch(url,{...init,headers,credentials:'same-origin'});let value;try{value=await res.json()}catch{throw new Error('The server returned an unreadable response.')}if(res.status===401&&url!='/api/auth/login'){showAuth();throw new Error(value.error||'Please sign in again.')}if(!res.ok){if(value.code==='PASSWORD_CHANGE_REQUIRED')showPasswordChange(true);throw new Error(value.error||'The request failed.')}return value}
function showAuth(mode='login'){$('#loginView').classList.remove('hidden');$('#appView').classList.add('hidden');state.user=null;state.initialPassword='';const reset=mode==='reset',forgot=mode==='forgot';$('#authTitle').textContent=reset?'Choose a new password':forgot?'Reset your password':'Welcome back.';$('#authIntro').textContent=reset?'Set a personal password to secure your account.':forgot?'Enter your account email to request a reset link.':'Sign in to your organisation’s IT control workspace.';$('#authFields').innerHTML=reset?field('New password',input('password','','password',true,'minlength="12" autocomplete="new-password"'))+field('Confirm password',input('confirm','','password',true,'minlength="12" autocomplete="new-password"')):field('Email address',input('email','','email',true,'autocomplete="username"'))+(forgot?'':field('Password',input('password','','password',true,'autocomplete="current-password"')));$('#authSubmit').textContent=reset?'Update password':forgot?'Request reset link':'Sign in';$('#authForm').dataset.mode=mode;$('#authMessage').textContent='';$('#forgotLink').classList.toggle('hidden',forgot||reset);$('#backLogin').classList.toggle('hidden',!forgot&&!reset)}
function openDialog(title,body,wide=false){const el=$('#recordDialog');$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;el.classList.toggle('wide',wide);if(!el.open)el.showModal();bind(el);return el}
function closeDialog(){const el=$('#recordDialog');el.close();$('#dialogBody').innerHTML=''}
function formWrap(fields,label='Save',id='editForm'){return '<form id="'+id+'"><div class="form-grid">'+fields+'</div><div class="form-error" role="alert"></div><footer><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button primary">'+label+'</button></footer></form>'}
async function submitForm(form,work){const btn=form.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;form.querySelector('.form-error')?.replaceChildren();try{await work(Object.fromEntries(new FormData(form).entries()))}catch(e){const el=form.querySelector('.form-error');if(el)el.textContent=e.message;else notify(e.message,true)}finally{if(btn)btn.disabled=false}}
function credentialsCard(title,user,password){openDialog(title,'<div class="credential-card"><p>'+esc(user.name||user.email)+'</p><dl><dt>Email</dt><dd>'+esc(user.email)+'</dd><dt>Temporary password</dt><dd><code id="shownPassword">'+esc(password)+'</code></dd></dl><p>Shown once. Expires in 24 hours. The user must choose a personal password at first sign-in.</p>'+button('Copy password','copy-password')+button('Done','close','','primary')+'</div>')}
async function showPasswordChange(forced=false){const fields=field(forced?'Temporary password':'Current password',input('current_password',state.initialPassword,'password',true,'autocomplete="current-password"'))+field('New personal password',input('new_password','','password',true,'minlength="12" maxlength="128" autocomplete="new-password"'))+field('Confirm new password',input('confirm','','password',true,'minlength="12" autocomplete="new-password"'));openDialog(forced?'Set your personal password':'Change password',formWrap(fields,'Update password','passwordForm'));$('#recordDialog').dataset.forced=forced?'true':'';$('#passwordForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{if(d.new_password!==d.confirm)throw new Error('Passwords do not match.');const result=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(d)});state.initialPassword='';state.user=result.user;state.permissions=result.permissions;$('#recordDialog').dataset.forced='';closeDialog();await enterWorkspace();notify('Personal password saved.')})}}
async function enterWorkspace(){state.boot=await api('/api/commercial/bootstrap');$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#userName').textContent=state.user.name;$('#userRole').textContent=state.user.role.replaceAll('_',' ');$('#userInitial').textContent=state.user.name.slice(0,1);$('#orgName').textContent=state.boot.organization.name;renderNav();await go(state.page)}
function renderNav(){$('#navigation').innerHTML=nav.map(([group,items])=>'<div class="nav-group"><span>'+group+'</span>'+items.filter(([p])=>(p!=='organizations'||state.boot.platform_admin)&&(p!=='users'||state.boot.can_admin)&&(p!=='audit'||has('audit.read'))&&(p!=='reports'||has('reports.read'))).map(([p,name,icon])=>'<button class="nav-item '+(state.page===p?'active':'')+'" data-page="'+p+'"><i>'+icon+'</i>'+name+'</button>').join('')+'</div>').join('');bind($('#navigation'))}
function toolbar(extra=''){return '<div class="toolbar"><label class="search"><span class="sr-only">Search records</span><input id="recordSearch" placeholder="Search reference or title…" value="'+esc(state.q)+'"></label><label class="source-filter"><span class="sr-only">Data source</span><select id="dataset"><option value="all">Actual + sample records</option><option value="actual" '+(state.dataset==='actual'?'selected':'')+'>Actual records only</option><option value="sample" '+(state.dataset==='sample'?'selected':'')+'>Sample records only</option></select></label><div class="toolbar-actions">'+extra+'</div></div>'}
function stats(items){return '<div class="stat-grid">'+items.map(([title,value,sub])=>'<article class="stat"><span>'+esc(title)+'</span><strong>'+esc(value??0)+'</strong><small>'+esc(sub||'')+'</small></article>').join('')+'</div>'}
function table(headers,rows){return '<div class="table-scroll"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
function empty(message='No records match this selection.'){return '<div class="empty-state"><span>▤</span><h3>'+message+'</h3><p>Add a record or adjust the selected filters.</p></div>'}
async function go(page,keep=false){const seq=++state.sequence;state.page=page;if(!keep){state.pageNo=1;state.q=''}$('#pageTitle').textContent=labels[page]||'IT Control Management';$('#content').innerHTML='<div class="loading">Loading '+esc(labels[page]||'workspace')+'…</div>';$('#sidebar').classList.remove('open');renderNav();if(location.pathname!=='/reset-password')history.replaceState(null,'','/?module='+page);try{let html;if(state.boot.modules[page])html=await renderWork(page);else{const fn={overview:overview,library:library,tests:tests,evidence:evidence,findings:findings,reports:reports,notifications:notifications,users:users,organizations:organizations,settings:settings,integrations:integrations,audit:audit}[page];html=await(fn?fn():overview())}if(seq!==state.sequence)return;$('#content').innerHTML=html;bind($('#content'));$('#dataset')?.addEventListener('change',e=>{state.dataset=e.target.value;state.pageNo=1;go(state.page,true)});let timer;$('#recordSearch')?.addEventListener('input',e=>{state.q=e.target.value;clearTimeout(timer);timer=setTimeout(()=>go(state.page,true),300)})}catch(e){if(seq===state.sequence)$('#content').innerHTML='<div class="error-panel" role="alert"><h3>This view could not load.</h3><p>'+esc(e.message)+'</p>'+button('Try again','refresh')+'</div>';bind($('#content'))}}
async function overview(){const d=await api('/api/commercial/dashboard?dataset='+state.dataset);state.core=d;const total=d.modules.reduce((n,r)=>n+r.total,0),overdue=d.modules.reduce((n,r)=>n+r.overdue,0),samples=d.modules.reduce((n,r)=>n+r.samples,0);return '<section class="welcome"><div><span class="eyebrow">YOUR CONTROL PROGRAMME</span><h2>Clear ownership.<br>Evidence you can follow.</h2><p>Plan reviews, test controls and turn findings into verified action.</p></div><div class="welcome-mark" aria-hidden="true">RX<span>CONTROL MANAGEMENT</span></div></section>'+toolbar()+stats([['Controls in register',d.core.controls,'Defined control procedures'],['Programme records',total,'Across planning, risk and operations'],['Open findings',d.core.findings,'Issues requiring remediation'],['Overdue work',overdue,'Open records past their due date']])+(samples?'<div class="sample-note">'+samples+' records in this view are labelled sample scenarios. Select Actual records only to exclude them.</div>':'')+'<div class="module-grid">'+Object.entries(state.boot.modules).map(([key,m])=>{const count=d.modules.find(x=>x.module===key)||{};return '<button class="module-card" data-page="'+key+'"><span>'+esc(m.prefix)+'</span><h3>'+esc(m.name)+'</h3><p>'+esc(m.description)+'</p><footer><strong>'+(count.total||0)+' records</strong><small>'+(count.overdue||0)+' overdue ↗</small></footer></button>'}).join('')+'</div><div class="two-col"><section class="panel"><div class="panel-heading"><h3>Next due & overdue</h3><span>Accountable work</span></div>'+table(['Reference','Record','Due','Status'],d.due.map(r=>'<tr data-open-record="'+r.id+'" data-module="'+r.module+'" tabindex="0"><td>'+esc(r.reference)+'</td><td>'+esc(r.title)+sample(r)+'</td><td class="'+(r.due_date<today()?'overdue':'')+'">'+fmt(r.due_date)+'</td><td>'+badge(r.status)+'</td></tr>'))+'</section><section class="panel"><div class="panel-heading"><h3>Highest rated risks</h3><span>Likelihood × impact</span></div>'+d.risks.map(r=>'<div class="risk-line"><span>'+esc(r.title)+'</span><b>'+r.score+' / 25</b><meter max="25" value="'+r.score+'">'+r.score+'</meter></div>').join('')+(!d.risks.length?empty('No risks recorded yet.'):'')+'</section></div>'}
async function renderWork(module){const p=new URLSearchParams({dataset:state.dataset,q:state.q,page:String(state.pageNo)}),d=await api('/api/work/'+module+'?'+p);state.list=d;const def=state.boot.modules[module];let extra=state.boot.can_write?button('＋ Add '+def.singular.toLowerCase(),'new-record',module,'primary'):'';if(module==='licences'&&state.boot.can_admin)extra=button('Import Excel / CSV','import-licences')+extra;extra+=button('Export Excel','export',module+'|xlsx');return '<div class="section-intro"><p>'+esc(def.description)+'</p></div>'+toolbar(extra)+stats([['Records',d.summary.total,'In this module and selection'],['Open',d.summary.open,'Work or active records'],['Overdue',d.summary.overdue,'Open records past due'],['Awaiting review',d.summary.pending,'Submitted work and implementation']])+(d.summary.samples?'<div class="sample-note">'+d.summary.samples+' fictional sample records in this selection. Sample scenarios are read-only.</div>':'')+'<section class="panel flush">'+(d.records.length?table(['Reference / record','Owner','Priority',module==='risks'?'Risk rating':'Status','Due / renewal date',''],d.records.map(r=>'<tr><td><button class="record-title" data-action="open-record" data-id="'+r.id+'" data-module="'+module+'"><small>'+esc(r.reference)+'</small><strong>'+esc(r.title)+'</strong></button>'+sample(r)+'</td><td>'+esc(r.owner_name)+'</td><td>'+badge(r.priority)+'</td><td>'+(module==='risks'?'<strong class="risk-rating">'+(r.risk_score||'—')+' / 25</strong><small>Residual '+(r.residual_score||'—')+'</small>':badge(r.expired?'Expired':r.status))+'</td><td class="'+(r.due_date&&r.due_date<today()&&!['Closed','Retired','Completed'].includes(r.status)?'overdue':'')+'">'+fmt(r.due_date)+'</td><td>'+button('Open ↗','open-record',r.id)+'</td></tr>')):empty())+'<footer class="pagination"><span>'+d.total+' records · Page '+d.page+'</span><div>'+button('Previous','previous')+button('Next','next')+'</div></footer></section>'}
async function recordForm(module,r=null){const def=state.boot.modules[module];const [assets,parents,findingsRows]=await Promise.all([api('/api/work/assets?dataset=actual'),api('/api/work/plans?dataset=actual'),api('/api/findings?dataset='+state.dataset)]);const people=state.boot.users.filter(u=>u.status==='active'&&['admin','control_manager','control_officer','auditor'].includes(u.role));const owner=r?.owner_id||state.user.id;const reviewer=state.boot.users.filter(u=>u.status==='active'&&['admin','control_manager','reviewer','auditor'].includes(u.role)&&u.id!==owner&&u.id!==(r?.created_by||state.user.id));let fields=field('Title *',input('title',r?.title||'','text',true,'maxlength="240"'),true)+field('Description','<textarea name="description" rows="3" maxlength="6000">'+esc(r?.description||'')+'</textarea>',true)+field('Accountable owner *','<select name="owner_id" required>'+options(people,owner)+'</select>')+field('Independent reviewer','<select name="reviewer_id">'+options(reviewer,r?.reviewer_id)+'</select>',false,'Must differ from both creator and owner.')+field('Priority *','<select name="priority">'+['Low','Medium','High','Critical'].map(v=>'<option '+((r?.priority||'Medium')===v?'selected':'')+'>'+v+'</option>').join('')+'</select>');if(!['licences','slas'].includes(module))fields+=field('Due / review date'+(module==='assets'?'':' *'),input('due_date',r?.due_date||'','date',module!=='assets'));fields+=field('Related control','<select name="control_id">'+options(state.boot.controls.map(c=>({id:c.id,name:c.control_code+' · '+c.title})),r?.control_id)+'</select>');if(module!=='assets')fields+=field('Related asset / application','<select name="asset_id">'+options(assets.records,r?.asset_id)+'</select>');if(module==='reviews')fields+=field('Annual review plan','<select name="parent_id">'+options(parents.records,r?.parent_id)+'</select>');if(module==='actions')fields+=field('Related finding','<select name="finding_id">'+options(findingsRows.map(f=>({id:f.id,name:f.title})),r?.finding_id)+'</select>');
 for(const f of def.fields){const v=r?.details?.[f.key]??'';let body;if(f.type==='textarea')body='<textarea name="d_'+f.key+'" rows="3" maxlength="6000" '+(f.required?'required':'')+'>'+esc(v)+'</textarea>';else if(f.type==='select')body='<select name="d_'+f.key+'" '+(f.required?'required':'')+'>'+options(f.options.map(x=>({value:x,label:x})),v)+'</select>';else if(f.type==='evidence')body='<select name="d_'+f.key+'" multiple>'+state.boot.evidence.map(e=>'<option value="'+e.id+'" '+(Array.isArray(v)&&v.includes(e.id)?'selected':'')+'>'+esc(e.title)+'</option>').join('')+'</select>';else body=input('d_'+f.key,v,f.type==='date'?'date':['number','integer','rating','year','money','percentage'].includes(f.type)?'number':'text',f.required,'maxLength="6000" '+(['number','integer','rating','year','money','percentage'].includes(f.type)?'min="'+(f.type==='rating'?1:0)+'" step="'+(['integer','rating','year'].includes(f.type)?1:'.01')+'"':'')+(f.type==='rating'?' max="5"':''));fields+=field(f.label+(f.required?' *':''),body,f.type==='textarea');}
 openDialog((r?'Edit ':'Add ')+def.singular.toLowerCase(),formWrap(fields),true);const form=$('#editForm');form.querySelector('[name="owner_id"]').onchange=e=>{const selected=form.querySelector('[name="reviewer_id"]');selected.innerHTML=options(state.boot.users.filter(u=>u.status==='active'&&['admin','control_manager','reviewer','auditor'].includes(u.role)&&u.id!==Number(e.target.value)&&u.id!==(r?.created_by||state.user.id)),null)};
 form.onsubmit=e=>{e.preventDefault();submitForm(form,async d=>{const details={};for(const f of def.fields)details[f.key]=f.type==='evidence'?[...form.querySelector('[name="d_'+f.key+'"]').selectedOptions].map(o=>Number(o.value)):d['d_'+f.key]||'';const body={...d,details,version:r?.version,request_id:crypto.randomUUID()};await api('/api/work/'+module+(r?'/'+r.id:''),{method:r?'PUT':'POST',body:JSON.stringify(body)});closeDialog();await refreshBoot();await go(module,true);notify('Record saved.')})}}
async function openRecord(module,recordId){const d=await api('/api/work/'+module+'/'+recordId),r=d.record,def=state.boot.modules[module];state.selected={module,detail:d};let body=(r.is_sample?'<div class="sample-note">Fictional sample scenario · read-only. This is not an actual approval or assurance conclusion.</div>':'')+'<div class="detail-heading"><span>'+esc(r.reference)+'</span><h3>'+esc(r.title)+'</h3><p>'+esc(r.description)+'</p></div><div class="detail-facts"><div><small>Owner</small><strong>'+esc(r.owner_name)+'</strong></div><div><small>Reviewer</small><strong>'+esc(r.reviewer_name||'Not assigned')+'</strong></div><div><small>Status</small>'+badge(r.expired?'Expired':r.status)+'</div><div><small>Due / renewal</small><strong>'+fmt(r.due_date)+'</strong></div></div><dl class="detail-fields">'+def.fields.map(f=>'<div><dt>'+esc(f.label)+'</dt><dd>'+esc(Array.isArray(r.details[f.key])?r.details[f.key].join(', '):r.details[f.key]||'—')+'</dd></div>').join('')+'</dl>';
 if(!r.is_sample&&state.boot.can_write)body+='<div class="button-row">'+(!['Closed','Completed','Retired','Cancelled'].includes(r.status)?button('Edit record','edit-record',r.id):'')+(module==='licences'?button('Record renewal','renew',r.id,'primary'):'')+'</div>';
 if(!r.is_sample&&r.next_steps.length&&(state.boot.can_write||state.boot.can_review))body+='<section class="decision"><h4>Workflow decision</h4>'+formWrap(field('Next step *','<select name="to" required>'+options(r.next_steps.map(s=>({value:s,label:s})),null)+'</select>')+field('Decision / progress note *','<textarea name="note" required rows="2"></textarea>',true)+field('Outcome / completion notes','<textarea name="completion" rows="2"></textarea>',true)+field('Supporting evidence','<select name="evidence_ids" multiple>'+state.boot.evidence.map(e=>'<option value="'+e.id+'">'+esc(e.title)+'</option>').join('')+'</select>',true),'Save decision','decisionForm')+'</section>';
 body+='<section class="history"><h4>Decision history</h4>'+d.events.map(e=>'<article><strong>'+esc(e.action)+'</strong><time>'+fmt(e.created_at)+'</time><p>'+esc(e.note)+'</p><small>'+esc(e.actor_name)+'</small></article>').join('')+'</section>';if(d.renewals.length)body+='<section><h4>Renewal history</h4>'+table(['Previous expiry','New expiry','Payment date','GHS','Notes'],d.renewals.map(x=>'<tr><td>'+fmt(x.previous_expiry)+'</td><td>'+fmt(x.next_expiry)+'</td><td>'+fmt(x.payment_date)+'</td><td>'+(x.payment_minor==null?'—':(Number(x.payment_minor)/100).toFixed(2))+'</td><td>'+esc(x.notes)+'</td></tr>'))+'</section>';if(d.children.length)body+='<section><h4>Linked work</h4>'+d.children.map(c=>'<button class="linked-record" data-open-record="'+c.id+'" data-module="'+c.module+'">'+esc(c.reference)+' · '+esc(c.title)+' '+badge(c.status)+'</button>').join('')+'</section>';
 openDialog(def.singular+' · '+r.reference,body,true);$('#decisionForm')?.addEventListener('submit',e=>{e.preventDefault();submitForm(e.target,async f=>{f.evidence_ids=[...e.target.querySelector('[name="evidence_ids"]').selectedOptions].map(o=>Number(o.value));await api('/api/work/'+module+'/'+r.id+'/transition',{method:'POST',body:JSON.stringify({...f,version:r.version,request_id:crypto.randomUUID()})});await go(state.page,true);await openRecord(module,r.id);notify('Decision recorded.')})})}
function renewForm(){const r=state.selected.detail.record;openDialog('Record licence renewal',formWrap(field('Licence','<strong>'+esc(r.title)+'</strong>',true)+field('New expiry *',input('next_expiry','','date',true))+field('Payment date',input('payment_date',today(),'date'))+field('Payment amount (GHS)',input('payment_amount','','number',false,'min="0" step=".01"'))+field('Renewal notes','<textarea name="notes" rows="3"></textarea>',true),'Record renewal'));$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{await api('/api/work/licences/'+r.id+'/renew',{method:'POST',body:JSON.stringify({...d,version:r.version,request_id:crypto.randomUUID()})});closeDialog();await go('licences',true);notify('Renewal saved. Previous dates and payment remain in history.')})}}
async function library(){const rows=await api('/api/controls');state.controls=rows;const filtered=rows.filter(r=>(r.control_code+' '+r.title+' '+r.category).toLowerCase().includes(state.q.toLowerCase()));return '<div class="section-intro"><p>Control objectives, required evidence, framework references and testing criteria.</p></div>'+toolbar(has('controls.write')?button('＋ Add control','new-control','','primary'):'')+'<div class="library-grid">'+filtered.map(r=>'<article class="library-card"><header><span>'+esc(r.control_code)+'</span>'+badge(r.risk_level)+'</header><h3>'+esc(r.title)+'</h3><p>'+esc(r.description)+'</p><small>'+esc(r.framework_ref)+'</small><footer>'+button('Open control','control-detail',r.id)+(has('assessments.write')?button('Test control','test',r.id,'primary'):'')+'</footer></article>').join('')+'</div>'}
async function controlDetail(controlId){const d=await api('/api/controls/'+controlId);state.controlDetail=d;openDialog(d.control.control_code+' · '+d.control.title,'<p>'+esc(d.control.description)+'</p><dl class="detail-fields"><div><dt>Framework</dt><dd>'+esc(d.control.framework_ref)+'</dd></div><div><dt>Frequency</dt><dd>'+esc(d.control.frequency)+'</dd></div><div><dt>Evidence required</dt><dd>'+esc(d.control.evidence_required)+'</dd></div><div><dt>Testing criteria</dt><dd>'+esc(d.control.testing_criteria||'Assess design and operating effectiveness against the objective, approved policy and evidence requirements.')+'</dd></div></dl><div class="button-row">'+(has('controls.write')?button('Edit control','edit-control',controlId):'')+(has('assessments.write')?button('Test control','test',controlId,'primary'):'')+'</div><h4>Linked evidence</h4>'+d.evidence.map(e=>'<p>'+esc(e.title)+' '+badge(e.review_status)+'</p>').join('')+'<h4>Tests and findings</h4>'+d.tests.map(t=>'<p>'+esc(t.period)+' · '+badge(t.result)+' '+badge(t.review_status)+'</p>').join('')+d.findings.map(f=>'<p>'+esc(f.title)+' '+badge(f.status)+'</p>').join(''),true)}
function controlForm(r=null){const fields=field('Control code *',input('control_code',r?.control_code||'','text',true))+field('Title *',input('title',r?.title||'','text',true))+field('Description / objective','<textarea name="description" rows="3">'+esc(r?.description||'')+'</textarea>',true)+field('Control category *',input('category',r?.category||'IT General Controls','text',true))+field('Framework reference',input('framework_ref',r?.framework_ref||''))+field('Owner',input('owner',r?.owner||''))+field('Assigned officer','<select name="assigned_user_id">'+options(state.boot.users.filter(u=>u.status==='active'&&['control_manager','control_officer'].includes(u.role)),r?.assigned_user_id)+'</select>')+field('Frequency','<select name="frequency">'+options(['Continuous','Daily','Weekly','Monthly','Quarterly','Semi-Annual','Annual'].map(x=>({value:x,label:x})),r?.frequency||'Quarterly')+'</select>')+field('Risk level','<select name="risk_level">'+options(['Low','Medium','High'].map(x=>({value:x,label:x})),r?.risk_level||'Medium')+'</select>')+field('Evidence required','<textarea name="evidence_required" rows="3">'+esc(r?.evidence_required||'')+'</textarea>',true)+field('Testing criteria','<textarea name="testing_criteria" rows="3">'+esc(r?.testing_criteria||'')+'</textarea>',true);openDialog(r?'Edit control':'Add control',formWrap(fields),true);$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{d.assigned_user_id=d.assigned_user_id?Number(d.assigned_user_id):null;await api('/api/controls'+(r?'/'+r.id:''),{method:r?'PUT':'POST',body:JSON.stringify(d)});closeDialog();await refreshBoot();await go('library',true);notify('Control saved.')})}}
async function tests(){const rows=await api('/api/assessments?dataset='+state.dataset);state.tests=rows;return toolbar(has('assessments.write')?button('＋ Test a control','test','','primary'):'')+'<section class="panel flush">'+(rows.length?table(['Control','Period','Tester','Result','Score','Review',''],rows.map(r=>'<tr><td>'+esc(r.control_code)+'<small>'+esc(r.control_title)+'</small></td><td>'+esc(r.period)+sample(r)+'</td><td>'+esc(r.tester_name||'Starter scenario')+'</td><td>'+badge(r.result)+'</td><td>'+esc(r.score)+'%</td><td>'+badge(r.review_status)+'</td><td>'+button('View / review','review-test',r.id)+'</td></tr>')):empty('No control tests yet.'))+'</section>'}
async function testForm(controlId){if(!has('assessments.write'))throw new Error('Your role cannot perform testing.');const evidence=await api('/api/evidence?dataset=actual');let fields=field('Control *','<select name="control_id" required>'+options(state.boot.controls.map(c=>({id:c.id,name:c.control_code+' · '+c.title})),controlId)+'</select>',true)+field('Testing period *',input('period','','text',true))+field('Result *','<select name="result" required>'+options(['Effective','Partially Effective','Ineffective'].map(x=>({value:x,label:x})),'Effective')+'</select>')+field('Test objective *','<textarea name="test_objective" required rows="2" minlength="5"></textarea>',true)+field('Test procedure *','<textarea name="test_procedure" required rows="3" minlength="5"></textarea>',true)+field('Sample size',input('sample_size','10','number',true,'min="1" step="1"'))+field('Exceptions',input('exception_count','0','number',true,'min="0" step="1"'))+field('Score (%)',input('score','100','number',true,'min="0" max="100"'))+field('Design effective?','<select name="design_effective"><option value="true">Yes</option><option value="false">No</option></select>')+field('Operating effective?','<select name="operating_effective"><option value="true">Yes</option><option value="false">No</option></select>')+field('Evidence used *','<select name="evidence_ids" multiple required></select>',true)+field('Conclusion / notes','<textarea name="notes" rows="3"></textarea>',true)+field('Raise a finding for an exception?','<select name="raise_finding"><option value="false">No</option><option value="true">Yes</option></select>');openDialog('Test a control',formWrap(fields,'Submit for independent review'),true);const form=$('#editForm'),control=form.querySelector('[name="control_id"]');function updateEvidence(){form.querySelector('[name="evidence_ids"]').innerHTML=evidence.filter(e=>e.control_id===Number(control.value)).map(e=>'<option value="'+e.id+'">'+esc(e.title)+'</option>').join('')}control.onchange=updateEvidence;updateEvidence();form.onsubmit=e=>{e.preventDefault();submitForm(form,async d=>{const evidence_ids=[...form.querySelector('[name="evidence_ids"]').selectedOptions].map(o=>Number(o.value));for(const k of ['score','sample_size','exception_count'])d[k]=Number(d[k]);for(const k of ['design_effective','operating_effective','raise_finding'])d[k]=d[k]==='true';await api('/api/controls/'+d.control_id+'/test',{method:'POST',body:JSON.stringify({...d,evidence_ids})});closeDialog();await refreshBoot();await go('tests');notify('Control test submitted for independent review.')})}}
async function reviewTest(testId){const r=state.tests.find(t=>String(t.id)===String(testId));openDialog('Control test · '+r.control_code,'<dl class="detail-fields">'+['period','test_objective','test_procedure','sample_size','exception_count','result','score','notes'].map(k=>'<div><dt>'+esc(k.replaceAll('_',' '))+'</dt><dd>'+esc(r[k]??'—')+'</dd></div>').join('')+'</dl>'+((has('assessments.review')&&!r.is_sample&&r.tester_id!==state.user.id)?formWrap(field('Decision','<select name="review_status"><option>Reviewed</option><option>Needs Rework</option><option>Rejected</option></select>')+field('Review note *','<textarea name="review_notes" rows="3" required></textarea>',true),'Record review','reviewForm'):'<p class="muted">An independent reviewer must sign off this test.</p>'),true);$('#reviewForm')?.addEventListener('submit',e=>{e.preventDefault();submitForm(e.target,async d=>{await api('/api/assessments/'+r.id+'/review',{method:'POST',body:JSON.stringify(d)});closeDialog();await go('tests',true);notify('Review recorded.')})})}
async function evidence(){const rows=await api('/api/evidence?dataset='+state.dataset);state.evidence=rows;return toolbar(has('evidence.write')?button('＋ Upload evidence','upload','','primary'):'')+'<div class="evidence-grid">'+rows.filter(r=>(r.title+' '+r.control_code).toLowerCase().includes(state.q.toLowerCase())).map(r=>'<article class="evidence-card"><span class="document-icon">▣</span><div><span class="eyebrow">'+esc(r.control_code)+'</span><h3>'+esc(r.title)+sample(r)+'</h3><p>'+esc(r.source)+' · '+esc(r.period)+'</p>'+badge(r.review_status)+'<small class="hash">SHA-256: '+esc(r.sha256||'No source file')+'</small></div><footer>'+(r.file_id?button('Download','evidence-download',r.file_id):'')+((has('evidence.review')&&!r.is_sample&&r.uploaded_by!==state.user.id)?button('Review','review-evidence',r.id):'')+'</footer></article>').join('')+(!rows.length?empty('No evidence uploaded yet.'):'')+'</div>'}
function uploadForm(){const fields=field('Control *','<select name="control_id" required>'+options(state.boot.controls.map(c=>({id:c.id,name:c.control_code+' · '+c.title})),null)+'</select>',true)+field('Evidence title *',input('title','','text',true),true)+field('Period *',input('period','','text',true))+field('Evidence type','<select name="evidence_type"><option>Document</option><option>System Report</option><option>Approval</option><option>Screenshot</option></select>')+field('Source',input('source','Manual Upload'))+field('Original file *','<input type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.docx,.xlsx">',true,'Up to 8 MB. Original file and SHA-256 fingerprint are retained.');openDialog('Upload evidence',formWrap(fields,'Upload evidence'),true);$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{await api('/api/evidence/upload',{method:'POST',body:new FormData(e.target)});closeDialog();await refreshBoot();await go('evidence');notify('Evidence uploaded and fingerprinted.')})}}
function reviewEvidence(evidenceId){openDialog('Review evidence',formWrap(field('Decision','<select name="review_status"><option>Approved</option><option>Needs Update</option><option>Rejected</option></select>')+field('Review note *','<textarea name="review_notes" required rows="3"></textarea>',true),'Record review'));$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{await api('/api/evidence/'+evidenceId+'/review',{method:'POST',body:JSON.stringify(d)});closeDialog();await go('evidence');notify('Evidence review recorded.')})}}
async function findings(){const rows=await api('/api/findings?dataset='+state.dataset);state.findings=rows;return toolbar(has('findings.write')?button('＋ Record finding','new-finding','','primary'):'')+stats([['Findings',rows.length,'All recorded issues'],['Open',rows.filter(r=>!['Closed','Resolved'].includes(r.status)).length,'Requiring remediation'],['High severity',rows.filter(r=>r.severity==='High'&&!['Closed','Resolved'].includes(r.status)).length,'Open high-priority issues'],['Overdue',rows.filter(r=>r.due_date&&r.due_date.slice(0,10)<today()&&!['Closed','Resolved'].includes(r.status)).length,'Past agreed due date']])+'<section class="panel flush">'+(rows.length?table(['Finding / control','Severity','Owner','Due','Status',''],rows.filter(r=>r.title.toLowerCase().includes(state.q.toLowerCase())).map(r=>'<tr><td><strong>'+esc(r.title)+sample(r)+'</strong><small>'+esc(r.control_code||'Organisation-level finding')+'</small></td><td>'+badge(r.severity)+'</td><td>'+esc(r.owner||'Unassigned')+'</td><td>'+fmt(r.due_date)+'</td><td>'+badge(r.status)+'</td><td>'+button('Open / update','finding',r.id)+'</td></tr>')):empty('No findings recorded.'))+'</section>'}
function findingForm(r=null){if(r?.is_sample||!has('findings.write')){openDialog('Finding · '+(r?.title||''),'<p>'+esc(r?.description)+'</p>'+badge(r?.status)+sample(r||{}));return}let fields=field('Finding title *',input('title',r?.title||'','text',true),true)+field('Related control','<select name="control_id">'+options(state.boot.controls.map(c=>({id:c.id,name:c.control_code+' · '+c.title})),r?.control_id)+'</select>',true)+field('Severity','<select name="severity">'+options(['Low','Medium','High'].map(x=>({value:x,label:x})),r?.severity||'Medium')+'</select>')+field('Owner','<select name="owner_user_id">'+options(state.boot.users.filter(u=>u.status==='active'),r?.owner_user_id)+'</select>')+field('Due date',input('due_date',r?.due_date?.slice(0,10)||'','date'))+field('Status','<select name="status">'+options((r?['Open','In Progress','Pending Review','Resolved','Closed']:['Open','In Progress']).map(x=>({value:x,label:x})),r?.status||'Open')+'</select>')+field('Root cause','<textarea name="root_cause" rows="2">'+esc(r?.root_cause||'')+'</textarea>',true)+field('Recommendation','<textarea name="recommendation" rows="2">'+esc(r?.recommendation||'')+'</textarea>',true)+field('Completion / closure verification','<textarea name="completion_notes" rows="2">'+esc(r?.completion_notes||'')+'</textarea>',true)+field('Observation, impact and remediation','<textarea name="description" rows="5">'+esc(r?.description||'')+'</textarea>',true);if(r)fields+='<div class="wide muted">Closure requires an Effective retest performed after the finding, supported by evidence and reviewed independently.</div>';openDialog(r?'Finding · '+r.title:'Record a finding',formWrap(fields),true);$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{d.control_id=d.control_id?Number(d.control_id):null;d.owner_user_id=d.owner_user_id?Number(d.owner_user_id):null;await api('/api/findings'+(r?'/'+r.id:''),{method:r?'PUT':'POST',body:JSON.stringify(d)});closeDialog();await go('findings');notify('Finding saved.')})}}
async function reports(){return '<section class="report-hero"><span class="eyebrow">MANAGEMENT INFORMATION</span><h2>Export a clear view of the programme.</h2><p>Organisation-scoped reports include ownership, status, due dates, risk ratings and record details. Evidence and assurance packs retain their original source files.</p></section><section class="panel"><form id="reportForm" class="report-form">'+field('Report scope','<select name="module"><option value="all">All programme modules</option>'+Object.entries({...state.boot.modules,controls:{name:'Control Library'},tests:{name:'Control Testing'},evidence:{name:'Evidence Management'},findings:{name:'Findings Management'}}).map(([k,m])=>'<option value="'+k+'">'+esc(m.name)+'</option>').join('')+'</select>')+field('Data source','<select name="dataset"><option value="all">Actual + sample</option><option value="actual">Actual only</option><option value="sample">Sample only</option></select>')+'<div class="button-row">'+button('Download Excel','report-format','xlsx','primary')+button('Download PDF','report-format','pdf')+button('Download CSV','report-format','csv')+'</div></form></section><div class="two-col"><section class="panel"><h3>Full assurance pack</h3><p>Controls, tests, evidence register, findings, original evidence files and integrity manifest.</p>'+button('Download audit pack ZIP','audit-pack')+'</section><section class="panel"><h3>Control register</h3><p>Existing control health and assurance data as a spreadsheet-friendly register.</p>'+button('Download controls CSV','audit-csv')+'</section></div>'}
