async function users(){const rows=await api('/api/users');state.users=rows;return toolbar(state.boot.can_admin?button('＋ Add user','new-user','','primary'):'')+'<section class="panel flush">'+table(['Name / email','Role','Status','Actions'],rows.map(u=>'<tr><td><strong>'+esc(u.name)+'</strong><small>'+esc(u.email)+'</small></td><td>'+badge(u.role.replaceAll('_',' '))+'</td><td>'+badge(u.status)+'</td><td><div class="button-row">'+button('Issue temporary password','temporary-password',u.id)+(u.id!==state.user.id?button(u.status==='active'?'Disable':'Enable','user-status',u.id):'')+'</div></td></tr>'))+'</section>'}
