function integrationForm(key){const r=state.integrations.find(x=>x.provider_key===key),defs=key==='github'?{credentials:[['token','GitHub token','password']],config:[['repository','Repository (owner/name)','text']]}:r.connector_fields||{credentials:[],config:[]};let fields='';for(const group of ['credentials','config'])for(const f of defs[group]||[])fields+=field(esc(f[1]),input(group+'_'+f[0],'',f[2]||'text',!f[1].includes('optional'),'autocomplete="off" '+(f[3]?'placeholder="'+esc(f[3])+'"':'')));openDialog('Connect '+r.name,formWrap(fields,'Validate connection'),true);$('#editForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async d=>{const credentials={},config={};for(const[k,v]of Object.entries(d)){if(k.startsWith('credentials_'))credentials[k.slice(12)]=v;else if(k.startsWith('config_'))config[k.slice(7)]=v}const body=key==='github'?{token:credentials.token,repositories:config.repository?[config.repository]:[]}:{credentials,config};await api('/api/integrations/'+key+'/connect',{method:'POST',body:JSON.stringify(body)});closeDialog();notify('Provider connection validated.');await go('integrations')})}}
async function audit(){const rows=await api('/api/audit');return '<div class="section-intro"><p>Who performed an action, when it happened and which record was affected.</p></div><section class="panel flush">'+table(['Date','Actor','Action','Record type','Details'],rows.map(r=>'<tr><td>'+fmt(r.created_at)+'</td><td>'+esc(r.user_name||'System')+'</td><td>'+esc(r.action)+'</td><td>'+esc(r.entity_type)+'</td><td><details><summary>View details</summary><pre>'+esc(JSON.stringify(r.details,null,2))+'</pre></details></td></tr>'))+'</section>'}
async function importLicences(){openDialog('Import the ICDD licence register','<p>Use the same 14-column Excel/CSV template. Review the file before saving. Existing matching licences are skipped.</p>'+button('Download Excel template','licence-template')+formWrap(field('Accountable owner *','<select name="owner_id" required>'+options(state.boot.users.filter(u=>u.status==='active'&&['admin','control_manager','control_officer','auditor'].includes(u.role)),state.user.id)+'</select>')+field('Excel .xlsx or CSV *','<input name="file" type="file" accept=".xlsx,.csv" required>',true),'Preview import','importForm')+'<div id="importPreview"></div>',true);$('#importForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{const form=e.target,d=await api('/api/commercial/licences/parse',{method:'POST',body:new FormData(form)});state.import={rows:d.rows,owner_id:Number(form.owner_id.value)};$('#importPreview').innerHTML='<h4>'+d.total+' rows · '+d.rows.length+' valid · '+d.errors.length+' errors</h4>'+d.errors.map(x=>'<p class="error">Row '+x.row+': '+esc(x.message)+'</p>').join('')+table(['Item','Vendor','Expiry','Seats'],d.rows.slice(0,20).map(r=>'<tr><td>'+esc(r.title)+'</td><td>'+esc(r.details.vendor)+'</td><td>'+fmt(r.details.expiry_date)+'</td><td>'+esc(r.details.seat_count)+'</td></tr>'))+(!d.errors.length&&d.rows.length?button('Import '+d.rows.length+' licences','confirm-import','','primary'):'');bind($('#importPreview'))})}}
async function download(url,name){const r=await fetch(url,{credentials:'same-origin'});if(!r.ok){let d;try{d=await r.json()}catch{}throw new Error(d?.error||'Download failed.');}const disposition=r.headers.get('Content-Disposition')||'',matched=disposition.match(/filename="([^"]+)"/);if(matched)name=matched[1];const blob=await r.blob(),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)}
async function refreshBoot(){state.boot=await api('/api/commercial/bootstrap')}
function bind(root){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));root.querySelectorAll('[data-open-record]').forEach(b=>{b.onclick=()=>openRecord(b.dataset.module,b.dataset.openRecord);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action,recordId=b.dataset.id;try{
 if(a==='close'){if($('#recordDialog').dataset.forced)return;closeDialog()}
 if(a==='refresh')await go(state.page,true);
 if(a==='new-record')await recordForm(recordId);
 if(a==='open-record')await openRecord(b.dataset.module||state.page,recordId);
 if(a==='edit-record')await recordForm(state.selected.module,state.selected.detail.record);
 if(a==='renew')renewForm();
 if(a==='previous'&&state.pageNo>1){state.pageNo--;await go(state.page,true)}
 if(a==='next'&&state.list&&state.pageNo*state.list.size<state.list.total){state.pageNo++;await go(state.page,true)}
 if(a==='new-control')controlForm();if(a==='edit-control')controlForm(state.controlDetail.control);if(a==='control-detail')await controlDetail(recordId);if(a==='test')await testForm(recordId?Number(recordId):null);if(a==='review-test')await reviewTest(recordId);
 if(a==='upload')uploadForm();if(a==='review-evidence')reviewEvidence(recordId);if(a==='evidence-download')await download('/api/evidence/files/'+recordId,'control-evidence-'+recordId);
 if(a==='new-finding')findingForm();if(a==='finding')findingForm(state.findings.find(f=>String(f.id)===recordId));
 if(a==='export'){const [module,format]=recordId.split('|');await download('/api/commercial/reports/'+format+'?module='+module+'&dataset='+state.dataset,'it-control-'+module+'.'+format)}
 if(a==='report-format'){const d=Object.fromEntries(new FormData($('#reportForm')).entries());await download('/api/commercial/reports/'+recordId+'?'+new URLSearchParams(d),'it-control-report.'+recordId)}
 if(a==='audit-pack')await download('/api/reports/audit-pack.zip','it-control-audit-pack.zip');if(a==='audit-csv')await download('/api/reports/audit-pack.csv','it-control-register.csv');
 if(a==='integration')integrationForm(recordId);if(a==='sync-integration'){await api('/api/integrations/'+recordId+'/sync',{method:'POST',body:'{}'});notify('Provider sync completed.');await go('integrations')}if(a==='new-user')userForm();if(a==='temporary-password'){const d=await api('/api/commercial/users/'+recordId+'/temporary-password',{method:'POST',body:'{}'});credentialsCard('Temporary password issued',d.user,d.temporary_password)}
 if(a==='user-status'){const u=state.users.find(u=>String(u.id)===recordId);await api('/api/users/'+u.id+'/status',{method:'PUT',body:JSON.stringify({status:u.status==='active'?'disabled':'active'})});await refreshBoot();await go('users')}
 if(a==='copy-password'){await navigator.clipboard.writeText($('#shownPassword').textContent);notify('Temporary password copied.')}
 if(a==='new-organization')organizationForm();if(a==='organization')organizationForm(state.organizations.find(o=>String(o.id)===recordId));if(a==='change-password')await showPasswordChange();
 if(a==='toggle-notifications'){await api('/api/commercial/notifications/settings',{method:'PUT',body:JSON.stringify({enabled:!state.boot.organization.notifications_enabled})});await refreshBoot();await go('notifications')}
 if(a==='run-notifications'){const result=await api('/api/commercial/notifications/run',{method:'POST',body:'{}'});notify(result.queued+' notification messages prepared.');await go('notifications')}
 if(a==='import-licences')await importLicences();if(a==='licence-template')await download('/api/commercial/licences/template','ICDD-Licence-Template.xlsx');if(a==='confirm-import'){b.disabled=true;const result=await api('/api/commercial/licences/import',{method:'POST',body:JSON.stringify({...state.import,request_id:crypto.randomUUID()})});state.import=null;closeDialog();await go('licences');notify(result.inserted+' imported; '+result.skipped+' duplicates skipped.')}
 }catch(e){notify(e.message,true)}finally{if(b.isConnected)b.disabled=false}});root.querySelector('#settingsForm')?.addEventListener('submit',e=>{e.preventDefault();submitForm(e.target,async d=>{await api('/api/settings/organization',{method:'PUT',body:JSON.stringify(d)});await refreshBoot();notify('Organisation settings saved.')})})}
$('#authForm').onsubmit=async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form).entries()),mode=form.dataset.mode,submit=$('#authSubmit');submit.disabled=true;$('#authMessage').textContent='';try{if(mode==='forgot'){const d=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify(data)});$('#authMessage').textContent=d.message}else if(mode==='reset'){if(data.password!==data.confirm)throw new Error('Passwords do not match.');await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:state.resetToken,password:data.password})});state.resetToken='';showAuth();$('#authMessage').textContent='Password updated. Sign in with your new password.'}else{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});state.user=d.user;state.permissions=d.permissions;state.initialPassword=data.password;if(d.user.mustChange)await showPasswordChange(true);else{state.initialPassword='';await enterWorkspace()}}}catch(e){$('#authMessage').textContent=e.message}finally{submit.disabled=false}};
$('#forgotLink').onclick=()=>showAuth('forgot');$('#backLogin').onclick=()=>showAuth();$('#logoutBtn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}showAuth()};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#refreshBtn').onclick=async()=>{await refreshBoot();await go(state.page,true)};$('#dialogClose').onclick=()=>{if(!$('#recordDialog').dataset.forced)closeDialog()};$('#recordDialog').addEventListener('cancel',e=>{if($('#recordDialog').dataset.forced)e.preventDefault()});
async function start(){try{localStorage.removeItem('revolt_token')}catch{}if(location.pathname==='/reset-password'&&state.resetToken){history.replaceState(null,'','/reset-password');showAuth('reset');return}const module=new URLSearchParams(location.search).get('module');if(module&&labels[module])state.page=module;try{const d=await api('/api/auth/me');state.user=d.user;state.permissions=d.permissions;if(state.user.mustChange){showAuth();await showPasswordChange(true)}else await enterWorkspace()}catch{showAuth()}}
start();
